APG_SOURCE = '// Supply Chain Platform — APG composition example.\n// Demonstrates: Vendor Management, Procurement, Inventory,\n// Transport (Fleet + Routing + Tracking) composability.\n// Pipeline: procurement-to-delivery with vendor qualification rules,\n// transport optimisation, and real-time tracking.\n\nmodule supply_chain_platform version 1.0.0 {\n    description: "End-to-end supply chain platform composing vendor management, procurement, inventory, and transport capabilities";\n}\n\n// ── Foundation ───────────────────────────────────────────────────────────────\n\ncapability AuditLog {\n    contract: {\n        id: audit_log,\n        provides: [audit_events, compliance_trail],\n        configuration: {retention_days: 2555, immutable: true}\n    };\n    streaming: {processor: bytewax, state: audit_log_state};\n}\n\ncapability TenantContext {\n    contract: {\n        id: tenant_context,\n        provides: [tenant_context, rbac_policies],\n        requires: [audit_events],\n        configuration: {multi_tenant: true, isolation: "strict"}\n    };\n    master_data: {entities: [tenant, organisation, user, role]};\n}\n\n// ── Vendor Management ─────────────────────────────────────────────────────────\n\ncapability VendorManagement {\n    contract: {\n        id: vendor_management,\n        name: "Vendor Management",\n        version: "1.0.0",\n        provides: [vendor_master, vendor_qualifications, vendor_scorecards],\n        requires: [audit_events, tenant_context],\n        configuration: {\n            qualification_validity_days: 365,\n            min_score_to_approve: 70,\n            currency: "KES"\n        },\n        rules: [\n            {name: "vendor_tax_pin_required", when: "tax_pin missing", action: "deny"},\n            {name: "vendor_bank_details_required", when: "bank_account missing", action: "deny"},\n            {name: "expired_qualification_blocked", when: "qualification_expired", action: "deny"},\n            {name: "low_score_vendor_review", when: "vendor_score < min_score_to_approve", action: "require_review"}\n        ],\n        ui: {\n            shell: python,\n            routes: [\n                {name: "Vendors", path: "/scm/vendors", component: "VendorListScreen"},\n                {name: "Qualifications", path: "/scm/vendors/qualify", component: "QualificationScreen"},\n                {name: "Scorecards", path: "/scm/vendors/scorecards", component: "VendorScorecardScreen"}\n            ]\n        },\n        theme: {name: supply_chain_theme, tokens: {accent: "#2B6CB0"}}\n    };\n\n    erp_modules: [procurement, finance, compliance];\n    master_data: {entities: [vendor, qualification_certificate, bank_account, tax_record]};\n    approvals: {levels: 2, approvers: [procurement_officer, compliance_manager]};\n    streaming: {processor: bytewax, state: vendor_qualification_state};\n}\n\n// ── Procurement ───────────────────────────────────────────────────────────────\n\ncapability Procurement {\n    contract: {\n        id: procurement,\n        name: "Procurement",\n        version: "1.0.0",\n        provides: [purchase_requests, purchase_orders, rfq_management, goods_receipt],\n        requires: [vendor_master, vendor_qualifications, audit_events, tenant_context],\n        configuration: {\n            currency: "KES",\n            approval_threshold_low: 50000,\n            approval_threshold_high: 500000,\n            three_quote_minimum_above: 100000\n        },\n        rules: [\n            {name: "budget_code_required", when: "budget_code missing", action: "deny"},\n            {name: "unqualified_vendor_blocked", when: "vendor_qualified = false", action: "deny"},\n            {name: "three_quote_rule", when: "amount > three_quote_minimum_above AND quote_count < 3", action: "require_review"},\n            {name: "high_value_cfo_approval", when: "amount > approval_threshold_high", action: "require_review"},\n            {name: "po_requires_pr", when: "purchase_request_id missing", action: "deny"},\n            {name: "grn_quantity_mismatch", when: "received_qty != ordered_qty AND variance_pct > 5", action: "warn"}\n        ],\n        ui: {\n            shell: python,\n            routes: [\n                {name: "Purchase Requests", path: "/scm/procurement/pr", component: "PurchaseRequestScreen"},\n                {name: "Purchase Orders", path: "/scm/procurement/po", component: "PurchaseOrderScreen"},\n                {name: "RFQ", path: "/scm/procurement/rfq", component: "RFQScreen"},\n                {name: "Goods Receipt", path: "/scm/procurement/grn", component: "GoodsReceiptScreen"}\n            ]\n        },\n        theme: {name: supply_chain_theme, tokens: {accent: "#2B6CB0"}}\n    };\n\n    erp_modules: [procurement, finance, inventory];\n    components: {\n        requisition: {capability: purchase_requests, permissions: [create, approve, cancel]},\n        ordering: {capability: purchase_orders, permissions: [create, approve, dispatch, close]},\n        receiving: {capability: goods_receipt, permissions: [receive, inspect, reject]}\n    };\n    approvals: {levels: 3, approvers: [department_head, procurement_lead, cfo]};\n    master_data: {entities: [purchase_request, purchase_order, rfq, goods_receipt_note, supplier_quote]};\n    streaming: {processor: bytewax, state: procurement_workflow_state};\n\n    screens: {\n        ApprovalWorkbench: {\n            route: "/scm/procurement/approvals",\n            layout: split,\n            contains: [PendingPRList, POApprovalPanel],\n            binds: [purchase_requests.pending, purchase_orders.pending_approval],\n            actions: [approve, reject, request_revision]\n        }\n    };\n}\n\nworkflow ProcurementToPO {\n    steps: str = "draft -> budget_check -> vendor_selection -> rfq -> po_raised -> approved -> dispatched";\n    stages: str = "draft, review, approval, execution";\n    process: () -> bool = {\n        return true;\n    };\n}\n\n// ── Inventory ─────────────────────────────────────────────────────────────────\n\ncapability Inventory {\n    contract: {\n        id: inventory,\n        name: "Inventory Management",\n        version: "1.0.0",\n        provides: [stock_balances, stock_movements, reorder_alerts, warehouse_locations],\n        requires: [goods_receipt, audit_events, tenant_context],\n        configuration: {\n            default_warehouse: "NBO-WH-01",\n            reorder_lead_time_days: 14,\n            cycle_count_frequency_days: 30,\n            negative_stock_allowed: false\n        },\n        rules: [\n            {name: "no_negative_stock", when: "on_hand - reserved < 0 AND negative_stock_allowed = false", action: "deny"},\n            {name: "reorder_point_alert", when: "on_hand <= reorder_level", action: "warn"},\n            {name: "bin_location_required", when: "operation = putaway AND bin_location missing", action: "deny"},\n            {name: "expired_stock_quarantine", when: "expiry_date < today", action: "deny"}\n        ],\n        ui: {\n            shell: python,\n            routes: [\n                {name: "Stock Levels", path: "/scm/inventory/stock", component: "StockLevelScreen"},\n                {name: "Movements", path: "/scm/inventory/movements", component: "MovementScreen"},\n                {name: "Reorder Alerts", path: "/scm/inventory/reorder", component: "ReorderAlertScreen"},\n                {name: "Cycle Count", path: "/scm/inventory/cyclecount", component: "CycleCountScreen"}\n            ]\n        },\n        theme: {name: supply_chain_theme, tokens: {accent: "#276749"}}\n    };\n\n    erp_modules: [inventory, warehouse, procurement];\n    master_data: {entities: [stock_item, warehouse, bin_location, stock_movement, reorder_rule]};\n    streaming: {processor: bytewax, state: inventory_movement_state};\n}\n\n// ── Fleet Management ──────────────────────────────────────────────────────────\n\ncapability FleetManagement {\n    contract: {\n        id: fleet_management,\n        name: "Fleet Management",\n        version: "1.0.0",\n        provides: [vehicle_registry, driver_registry, maintenance_schedules, fuel_records],\n        requires: [audit_events, tenant_context],\n        configuration: {\n            fuel_type: "diesel",\n            service_interval_km: 10000,\n            driver_licence_expiry_alert_days: 30\n        },\n        rules: [\n            {name: "expired_licence_blocked", when: "driver_licence_expired", action: "deny"},\n            {name: "overdue_service_blocked", when: "km_since_service > service_interval_km", action: "warn"},\n            {name: "vehicle_insurance_required", when: "insurance_expired", action: "deny"}\n        ],\n        ui: {\n            shell: python,\n            routes: [\n                {name: "Vehicles", path: "/scm/fleet/vehicles", component: "VehicleRegistryScreen"},\n                {name: "Drivers", path: "/scm/fleet/drivers", component: "DriverRegistryScreen"},\n                {name: "Maintenance", path: "/scm/fleet/maintenance", component: "MaintenanceScreen"}\n            ]\n        },\n        theme: {name: supply_chain_theme, tokens: {accent: "#744210"}}\n    };\n\n    erp_modules: [transport, maintenance, hr];\n    master_data: {entities: [vehicle, driver, maintenance_record, fuel_log, insurance_policy]};\n    streaming: {processor: bytewax, state: fleet_telemetry_state};\n}\n\n// ── Route Optimisation ────────────────────────────────────────────────────────\n\ncapability RouteOptimisation {\n    contract: {\n        id: route_optimisation,\n        name: "Route Optimisation",\n        version: "1.0.0",\n        provides: [optimised_routes, delivery_plans, load_plans],\n        requires: [vehicle_registry, driver_registry, stock_balances, audit_events],\n        configuration: {\n            algorithm: "vrp_nearest_neighbour",\n            max_stops_per_route: 20,\n            max_load_kg: 5000,\n            time_window_enforcement: true\n        },\n        rules: [\n            {name: "overloaded_vehicle_denied", when: "load_kg > max_load_kg", action: "deny"},\n            {name: "driver_hours_limit", when: "planned_hours > 10", action: "deny"},\n            {name: "time_window_violation", when: "eta > delivery_window_end", action: "warn"}\n        ],\n        ui: {\n            shell: python,\n            routes: [\n                {name: "Route Planner", path: "/scm/transport/routes", component: "RoutePlannerScreen"},\n                {name: "Load Plans", path: "/scm/transport/loads", component: "LoadPlanScreen"}\n            ]\n        },\n        theme: {name: supply_chain_theme, tokens: {accent: "#744210"}}\n    };\n\n    erp_modules: [transport, logistics, warehouse];\n    master_data: {entities: [route, stop, delivery_plan, load_plan, time_window]};\n    streaming: {processor: bytewax, state: route_optimisation_state};\n}\n\n// ── Real-Time Tracking ────────────────────────────────────────────────────────\n\ncapability ShipmentTracking {\n    contract: {\n        id: shipment_tracking,\n        name: "Shipment Tracking",\n        version: "1.0.0",\n        provides: [shipment_positions, eta_updates, delivery_confirmations, exception_alerts],\n        requires: [optimised_routes, vehicle_registry, audit_events, tenant_context],\n        configuration: {\n            telemetry_interval_seconds: 30,\n            geofence_radius_metres: 500,\n            sms_eta_alerts: true,\n            pod_signature_required: true\n        },\n        rules: [\n            {name: "pod_required_on_delivery", when: "delivery_completed AND pod_captured = false", action: "deny"},\n            {name: "geofence_deviation_alert", when: "distance_from_route > geofence_radius_metres", action: "warn"},\n            {name: "temperature_excursion_alert", when: "temp_celsius > max_temp OR temp_celsius < min_temp", action: "warn"}\n        ],\n        ui: {\n            shell: python,\n            routes: [\n                {name: "Live Map", path: "/scm/tracking/live", component: "LiveTrackingMapScreen"},\n                {name: "Shipments", path: "/scm/tracking/shipments", component: "ShipmentListScreen"},\n                {name: "Exceptions", path: "/scm/tracking/exceptions", component: "ExceptionAlertScreen"}\n            ]\n        },\n        theme: {name: supply_chain_theme, tokens: {accent: "#744210"}}\n    };\n\n    erp_modules: [logistics, transport, customer_service];\n    master_data: {entities: [shipment, telemetry_event, geofence, proof_of_delivery]};\n    i18n: {supported_languages: [en, sw], default_language: en, fallback_language: en};\n    streaming: {processor: bytewax, state: shipment_tracking_state};\n\n    screens: {\n        LiveDispatchBoard: {\n            route: "/scm/tracking/dispatch",\n            layout: map_split,\n            contains: [LiveVehicleMap, ActiveShipmentList, ExceptionPanel],\n            binds: [shipment_positions.live, exception_alerts.active],\n            actions: [reassign_driver, contact_driver, escalate_exception]\n        }\n    };\n}\n\n// ── Procurement-to-Delivery Pipeline ─────────────────────────────────────────\n\nworkflow ProcurementToDelivery {\n    steps: str = "purchase_request -> vendor_qualification_check -> rfq -> po_approved -> goods_received -> warehouse_putaway -> pick_and_pack -> load_plan -> route_optimised -> dispatched -> in_transit -> delivered -> pod_captured";\n    stages: str = "planning, procurement, warehousing, dispatch, delivery, closure";\n    process: () -> bool = {\n        return true;\n    };\n}\n'
